use xiom.io;

use xiom.string;
fn validate_email(email: Str) -> Result[Str, Str] {
  let i = 0;
  let found = false;
  while i < str_len(email) {
    if string.str_slice(email, i, i + 1) == "@" { found = true; }
    i = i + 1;
  }
  if found { return Ok(email); }
  return Err("Invalid email: must contain @");
}

fn send_welcome(email: Str) {
  let result = validate_email(email);
  match result {
    Ok(valid) => io.println("Welcome email sent to " + valid.to_str()),
    Err(e) => io.println(e.to_str()),
  }
}

fn main() -> Int {
  send_welcome("alice@mail.com");
  send_welcome("bob");
  send_welcome("");
  return 0;
}
